#!/usr/bin/env python3
"""bundle.py — pack the working tree into the two BUILD bundles split.py reads.

Written chat 14. It had never been shipped: every prior build was bundled by an
ad-hoc script that did not survive its session, which is why HANDOFF-15 had to
name bundle.py among the tools a directive assumes and no tree contains.

  python3 bundle.py 15          writes The_Method_1_6_BUILD15_*.md and verifies

Bundle 1 = main volume + Register.  Bundle 2 = everything else.
Verification is a round trip: re-split the bundle in memory and require every
member byte-identical to the file on disk. A bundle that does not round-trip is
not written.
"""
import sys, os, re, glob

B1 = ["The_Method_1_6-2.md", "The_Method_1_6___The_Register-2.md"]
SKIP_EXT = {".prepoint", ".bak", ".pyc"}
SKIP_NAME = {"__pycache__"}


def members():
    out = []
    for f in sorted(os.listdir(".")):
        if not os.path.isfile(f):
            continue
        if f in SKIP_NAME or any(f.endswith(e) for e in SKIP_EXT):
            continue
        if f.startswith("The_Method_1_6_BUILD"):
            continue
        out.append(f)
    return out


def pack(names):
    parts = []
    for n in names:
        body = open(n, encoding="utf-8").read()
        parts.append(f"<<<FILE: {n}>>>\n{body}\n<<<END FILE: {n}>>>\n")
    return "\n".join(parts)


def unpack(text):
    d = {}
    for m in re.finditer(r'<<<FILE: (.+?)>>>\n(.*?)\n<<<END FILE: \1>>>', text, re.S):
        d[m.group(1)] = m.group(2)
    return d


def main(build):
    all_m = members()
    b1 = [f for f in B1 if f in all_m]
    b2 = [f for f in all_m if f not in b1]
    ok = True
    for tag, names in (("main_and_register", b1), ("compendia_papers_audits", b2)):
        text = pack(names)
        back = unpack(text)
        bad = [n for n in names
               if n not in back or back[n] != open(n, encoding="utf-8").read()]
        if bad:
            print(f"ROUND-TRIP FAIL {tag}: {bad[:5]}")
            ok = False
            continue
        fn = f"The_Method_1_6_BUILD{build}_{tag}.md"
        open(fn, "w", encoding="utf-8").write(text)
        print(f"{fn}  members {len(names)}  bytes {len(text.encode('utf-8')):,}  round-trip OK")
    if not ok:
        sys.exit(1)


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "15")

